-- composition of rule kernels L:decorrelate_predicate_subquery x L:eliminate_cross_join (datafusion), template not_exists
SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT (-1) AS c0, (1.0 / 3)::float8 AS c1 FROM t2 AS a1 WHERE (NOT EXISTS (SELECT 7 AS c0, 1.0::float8 AS c1))) SELECT 1.5::numeric AS c0, FALSE AS c1 FROM t2 AS a2 WHERE (('2024-12-31'::date = '2000-01-01'::date) OR ((ABS (3))::bigint >= LEAST (10::bigint, (SELECT COUNT (*) FROM cte1 AS a3))))) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT 100 AS c0, 1.5::numeric AS c1, 5 AS c2, 0::bigint AS c3 FROM (ti AS a1 INNER JOIN (t4 AS a2 JOIN t4 AS a3 ON (a2.c0 = a3.c0)) ON ((a1.c0 = a3.c0) AND TRUE)) GROUP BY a1.c1) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT 100 AS c0, 1.5::numeric AS c1, 5 AS c2, 0::bigint AS c3 FROM (ti AS a1 INNER JOIN (t4 AS a2 JOIN t4 AS a3 ON (a2.c0 = a3.c0)) ON ((a1.c0 = a3.c0) AND TRUE)) GROUP BY a1.c1) AS kb) = 0 THEN (SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT (-1) AS c0, (1.0 / 3)::float8 AS c1 FROM t2 AS a1 WHERE (NOT EXISTS (SELECT 7 AS c0, 1.0::float8 AS c1))) SELECT 1.5::numeric AS c0, FALSE AS c1 FROM t2 AS a2 WHERE (('2024-12-31'::date = '2000-01-01'::date) OR ((ABS (3))::bigint >= LEAST (10::bigint, (SELECT COUNT (*) FROM cte1 AS a3))))) AS ka) ELSE 0 END
